// Cyrus meshgen rung 3: STATIC SCAN of a model-written Blender script, run before the job is queued.
// NOT the security boundary. Python is too dynamic for a text scan to be complete, and bpy has escape hatches no
// list can enumerate. The real boundary is the sandbox (no network, user nobody, read-only fs, /opt and /tank hidden,
// 4G/400%/256-task caps, tmpfs work dir); a kernel escape from that systemd sandbox is UNTESTED, so production must
// run rung 3 on an isolated worker (microVM/gVisor) as well. The same rules are re-checked on the AST inside the
// sandbox by ./blender/mg_scratch.py (a test keeps the two lists equal). Pure.
import { SCRATCH_MAX_CHARS, SCRATCH_MAX_LINES } from "./spec";

export const ALLOWED_IMPORTS = ["bmesh", "bpy", "math", "mathutils", "random"] as const;
export const DENY_NAMES = ["eval", "exec", "compile", "open", "__import__", "globals", "locals", "vars", "getattr", "setattr", "delattr", "input", "breakpoint", "memoryview", "help", "exit", "quit", "dir", "type", "os", "sys", "subprocess", "socket", "ctypes", "importlib", "shutil", "pathlib", "io", "builtins", "__builtins__", "print_function"] as const;
export const DENY_ATTRS = ["app", "utils", "texts", "libraries", "images", "sounds", "fonts", "filepath", "filepath_raw", "save", "save_render", "reload", "handlers", "path", "preferences", "window_managers", "window_manager", "screens", "workspaces", "window", "screen", "area", "url_open", "driver_namespace", "msgbus", "types", "props", "timers", "render", "cameras", "lights", "worlds", "scenes", "node_groups", "execute", "system", "popen", "spawn", "environ"] as const;

export type ScanIssue = { line: number; code: string; message: string };

/** Split source into code (strings blanked to "") and the string literal bodies, dropping comments. */
export function splitPython(src: string): { code: string; strings: { line: number; text: string }[] } {
  let code = "", i = 0, line = 1;
  const strings: { line: number; text: string }[] = [];
  while (i < src.length) {
    const c = src[i];
    if (c === "\n") { code += c; line++; i++; continue; }
    if (c === "#") { while (i < src.length && src[i] !== "\n") i++; continue; }
    if (c === '"' || c === "'") {
      const triple = src.startsWith(c.repeat(3), i);
      const q = triple ? c.repeat(3) : c;
      const startLine = line;
      let j = i + q.length, body = "";
      while (j < src.length && !src.startsWith(q, j)) {
        if (src[j] === "\\") { body += src.slice(j, j + 2); j += 2; continue; }
        if (src[j] === "\n") { if (!triple) break; line++; }
        body += src[j]; j++;
      }
      strings.push({ line: startLine, text: body });
      code += '""';
      i = Math.min(src.length, j + q.length);
      continue;
    }
    code += c; i++;
  }
  return { code, strings };
}

export function scanScratchScript(src: string): ScanIssue[] {
  const out: ScanIssue[] = [];
  const add = (line: number, code: string, message: string) => out.push({ line, code, message });
  if (src.length > SCRATCH_MAX_CHARS) add(0, "too_long", `script is ${src.length} chars, the cap is ${SCRATCH_MAX_CHARS}`);
  if (src.split("\n").length > SCRATCH_MAX_LINES) add(0, "too_many_lines", `the cap is ${SCRATCH_MAX_LINES} lines`);
  if (out.length) return out;
  const { code, strings } = splitPython(src);
  const lines = code.split("\n");
  const allowed = new Set<string>(ALLOWED_IMPORTS), names = new Set<string>(DENY_NAMES), attrs = new Set<string>(DENY_ATTRS);
  lines.forEach((l, idx) => {
    const ln = idx + 1;
    const imp = /^\s*import\s+(.+)$/.exec(l);
    if (imp) for (const part of imp[1].split(",")) { const mod = part.trim().split(/\s+/)[0]; if (!allowed.has(mod.split(".")[0])) add(ln, "import_denied", `import ${mod} is not allowed (allowed: ${ALLOWED_IMPORTS.join(", ")})`); }
    const from = /^\s*from\s+(\S+)\s+import\s+(.+)$/.exec(l);
    if (from) {
      if (from[1].startsWith(".") || !allowed.has(from[1].split(".")[0])) add(ln, "import_denied", `from ${from[1]} import is not allowed`);
      if (/\*|(^|[\s,(])_/.test(from[2])) add(ln, "import_denied", "star or private imports are not allowed");
    }
    for (const m of l.matchAll(/(?<![.\w])([A-Za-z_]\w*)/g)) {
      const id = m[1];
      if (names.has(id) || id.startsWith("__")) add(ln, "name_denied", `${id} is not allowed`);
    }
    for (const m of l.matchAll(/\.\s*([A-Za-z_]\w*)/g)) {
      const a = m[1];
      if (a.startsWith("_")) add(ln, "private_attr", `.${a} is not allowed`);
      if (attrs.has(a)) add(ln, "attr_denied", `.${a} is not allowed`);
    }
    for (const m of l.matchAll(/([A-Za-z_]\w*|\))\s*\.\s*ops\b/g)) if (m[1] !== "bmesh") add(ln, "bpy_ops", "bpy.ops is not allowed; use bmesh and bpy.data");
    if (/(?<![.\w])bpy\b(?!\s*\.)/.test(l) && !imp && !from) add(ln, "bpy_alias", "use bpy only as bpy.<attr> (no aliasing)");
    if (/^\s*(global|nonlocal)\b/.test(l)) add(ln, "global_denied", "global/nonlocal are not allowed");
    if (/\b(async|await)\b/.test(l)) add(ln, "async_denied", "async code is not allowed");
  });
  for (const s of strings) if (s.text.includes("__")) add(s.line, "dunder_string", 'strings containing "__" are not allowed');
  if (!/^def\s+build\s*\(/m.test(code)) add(0, "no_build", "the script must define a top-level build(K) function");
  return out;
}
#!/bin/bash
# sbx-meshgen.sh -- run ONE meshgen job's Blender inside the node-2 sandbox (recipe from the 2026-10-10 PoC, sbx.sh).
# Runs as root ON node-2, outside the sandbox. Shipped inside each job's tar by lib/cyrus/meshgen/runner.ts.
#   sbx-meshgen.sh JOBDIR BLENDER_DIR MAX_SEC LOCK_WAIT_SEC
# JOBDIR/in   = harness + modules + request.json (+ scratch.py), read-only inside the sandbox
# JOBDIR/work = size-capped tmpfs owned by nobody, the only writable path inside the sandbox
# Writes JOBDIR/out.tar (work/ regular files + meta/) for the caller to fetch, then unmounts the tmpfs.
# Exit codes in meta/exit: blender's own, 75 = build lock busy, 124 = killed at RuntimeMaxSec.
set -uo pipefail
J="$1"; B="$2"; MAX="$3"; WAIT="$4"
ROOT=/tank/nxeon-build/tmp/meshgen/jobs
case "$J" in "$ROOT"/mg-*) ;; *) echo "bad job dir" >&2; exit 2 ;; esac
case "$(basename "$J")" in *[!a-z0-9-]*) echo "bad job id" >&2; exit 2 ;; esac
case "$MAX$WAIT" in *[!0-9]*) echo "bad limits" >&2; exit 2 ;; esac
[ "$(hostname)" = nxeon-fsn1 ] || { echo "must run on node-2" >&2; exit 2; }
[ -x "$B/blender" ] || { echo "no blender at $B" >&2; exit 2; }
mkdir -p "$J/work" "$J/meta"
chmod 755 "$J" "$J/in"; chmod 644 "$J/in"/*
mount -t tmpfs -o size=512m,mode=0755,uid=65534,gid=65534,nosuid,nodev,noexec cyrus-meshgen "$J/work" || { echo 70 > "$J/meta/exit"; exit 0; }
cleanup() {
  # copy only regular files (never symlinks/devices the sandbox may have made), capped at 64 MB in total
  ( cd "$J" && find work -maxdepth 1 -type f -size -48M -printf '%P\n' | head -40 | sed 's|^|work/|' > meta/files.txt
    tar --no-recursion -cf out.tar -T meta/files.txt meta/exit meta/log.txt meta/lock_wait_ms meta/wall_ms 2>/dev/null
    [ "$(stat -c %s out.tar 2>/dev/null || echo 0)" -le 67108864 ] || : > out.tar )
  umount "$J/work" 2>/dev/null || umount -l "$J/work" 2>/dev/null || true
}
trap cleanup EXIT
: > "$J/meta/log.txt"; echo 0 > "$J/meta/lock_wait_ms"; echo 0 > "$J/meta/wall_ms"
t0=$(date +%s%3N)
exec 7>>/run/lock/nxeon-build.lock
if ! flock -w "$WAIT" 7; then echo 75 > "$J/meta/exit"; exit 0; fi
t1=$(date +%s%3N); echo $((t1 - t0)) > "$J/meta/lock_wait_ms"
UNIT="cyrus-meshgen-$(basename "$J")"
systemd-run --quiet --pipe --wait --collect --unit="$UNIT" --slice=nxeon-build-agents.slice \
  -p Nice=10 -p IOSchedulingClass=best-effort -p IOSchedulingPriority=7 -p OOMScoreAdjust=1000 \
  -p RuntimeMaxSec="$MAX" -p KillMode=control-group -p TimeoutStopSec=5 \
  -p User=nobody -p Group=nogroup \
  -p MemoryMax=4G -p MemorySwapMax=0 -p CPUQuota=400% -p TasksMax=256 -p LimitCORE=0 -p LimitFSIZE=268435456 \
  -p PrivateNetwork=yes -p ProtectSystem=strict -p ProtectHome=tmpfs \
  -p TemporaryFileSystem=/tmp:size=256M,mode=1777 \
  -p TemporaryFileSystem=/opt:ro -p TemporaryFileSystem=/tank:ro -p TemporaryFileSystem=/mnt:ro -p TemporaryFileSystem=/srv:ro -p TemporaryFileSystem=/var/lib:ro \
  -p TemporaryFileSystem=/etc/pve:ro -p TemporaryFileSystem=/etc/nxeon-build:ro \
  -p BindReadOnlyPaths="$B" -p BindReadOnlyPaths="$J/in" -p BindPaths="$J/work" \
  -p ProtectKernelTunables=yes -p ProtectKernelModules=yes -p ProtectKernelLogs=yes -p ProtectControlGroups=yes -p ProtectClock=yes \
  -p NoNewPrivileges=yes -p CapabilityBoundingSet= -p RestrictNamespaces=yes -p LockPersonality=yes -p RestrictSUIDSGID=yes \
  -p WorkingDirectory="$J/work" \
  -E HOME=/tmp -E TMPDIR=/tmp -E LANG=C.UTF-8 -E PATH=/usr/bin:/bin \
  "$B/blender" --background --factory-startup --python-exit-code 3 --python "$J/in/mg_harness.py" -- "$J/in/request.json" \
  </dev/null 2>&1 | head -c 262144 > "$J/meta/log.txt"
rc=${PIPESTATUS[0]}
t2=$(date +%s%3N); echo $((t2 - t1)) > "$J/meta/wall_ms"
# systemd-run reports a RuntimeMaxSec kill as a failed unit; record it as 124 so the caller can say "timeout"
if [ "$rc" -ne 0 ] && [ $((t2 - t1)) -ge $((MAX * 1000)) ]; then rc=124; fi
echo "$rc" > "$J/meta/exit"
flock -u 7
exit 0

# mg_scratch.py -- rung 3 (from-scratch, model-written Blender Python): STATIC GUARD + restricted exec.
# THIS IS NOT THE SECURITY BOUNDARY. A script that passes still runs full CPython inside Blender, and bpy exposes
# escape hatches this guard cannot enumerate. The boundary is the sandbox around Blender (no network, user nobody,
# read-only fs, /opt and /tank hidden, memory/CPU/task caps, tmpfs work dir). Production must ALSO run it on an
# isolated worker (microVM / gVisor); a kernel escape from the systemd sandbox is untested.
# The same rules run in TypeScript before submit (lib/cyrus/meshgen/scan.ts); this copy re-checks inside the sandbox.
import ast

MAX_CHARS = 24000
MAX_LINES = 600
MAX_NODES = 20000
ALLOWED_IMPORTS = {'math', 'random', 'bmesh', 'mathutils', 'bpy'}
DENY_NAMES = {'eval', 'exec', 'compile', 'open', '__import__', 'globals', 'locals', 'vars', 'getattr', 'setattr', 'delattr',
              'input', 'breakpoint', 'memoryview', 'help', 'exit', 'quit', 'dir', 'type', 'os', 'sys', 'subprocess', 'socket',
              'ctypes', 'importlib', 'shutil', 'pathlib', 'io', 'builtins', '__builtins__', 'print_function'}
DENY_ATTRS = {'app', 'utils', 'texts', 'libraries', 'images', 'sounds', 'fonts', 'filepath', 'filepath_raw', 'save', 'save_render',
              'reload', 'handlers', 'path', 'preferences', 'window_managers', 'window_manager', 'screens', 'workspaces', 'window',
              'screen', 'area', 'url_open', 'driver_namespace', 'msgbus', 'types', 'props', 'timers', 'render', 'cameras', 'lights',
              'worlds', 'scenes', 'node_groups', 'execute', 'system', 'popen', 'spawn', 'environ'}


def check(src):
    """-> list of {line, code, message}. Empty list = passed the static rules (still sandboxed)."""
    out = []
    add = lambda line, code, msg: out.append({'line': line, 'code': code, 'message': msg})
    if len(src) > MAX_CHARS: add(0, 'too_long', f'script is {len(src)} chars, the cap is {MAX_CHARS}')
    if src.count('\n') + 1 > MAX_LINES: add(0, 'too_many_lines', f'the cap is {MAX_LINES} lines')
    if out: return out
    try:
        tree = ast.parse(src, filename='scratch.py')
    except SyntaxError as e:
        return [{'line': e.lineno or 0, 'code': 'syntax', 'message': str(e.msg)}]
    nodes = list(ast.walk(tree))
    if len(nodes) > MAX_NODES: return [{'line': 0, 'code': 'too_complex', 'message': f'more than {MAX_NODES} syntax nodes'}]
    parents = {}
    for n in nodes:
        for c in ast.iter_child_nodes(n): parents[c] = n
    has_build = False
    for n in nodes:
        ln = getattr(n, 'lineno', 0)
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.name.split('.')[0] not in ALLOWED_IMPORTS: add(ln, 'import_denied', f'import {a.name} is not allowed (allowed: {sorted(ALLOWED_IMPORTS)})')
        elif isinstance(n, ast.ImportFrom):
            if (n.module or '').split('.')[0] not in ALLOWED_IMPORTS or n.level: add(ln, 'import_denied', f'from {n.module} import is not allowed')
            for a in n.names:
                if a.name == '*' or a.name.startswith('_'): add(ln, 'import_denied', 'star or private imports are not allowed')
        elif isinstance(n, ast.Name):
            if n.id in DENY_NAMES or n.id.startswith('__'): add(ln, 'name_denied', f'{n.id} is not allowed')
            if n.id == 'bpy' and not isinstance(parents.get(n), ast.Attribute): add(ln, 'bpy_alias', 'use bpy only as bpy.<attr> (no aliasing)')
        elif isinstance(n, ast.Attribute):
            if n.attr.startswith('_'): add(ln, 'private_attr', f'.{n.attr} is not allowed')
            if n.attr in DENY_ATTRS: add(ln, 'attr_denied', f'.{n.attr} is not allowed')
            if n.attr == 'ops' and not (isinstance(n.value, ast.Name) and n.value.id == 'bmesh'): add(ln, 'bpy_ops', 'bpy.ops is not allowed; use bmesh and bpy.data')
        elif isinstance(n, ast.Constant) and isinstance(n.value, str):
            if '__' in n.value: add(ln, 'dunder_string', 'strings containing "__" are not allowed')
        elif isinstance(n, (ast.Global, ast.Nonlocal)):
            add(ln, 'global_denied', 'global/nonlocal are not allowed')
        elif isinstance(n, (ast.AsyncFunctionDef, ast.Await, ast.AsyncFor, ast.AsyncWith)):
            add(ln, 'async_denied', 'async code is not allowed')
        elif isinstance(n, ast.FunctionDef) and n.name == 'build' and isinstance(parents.get(n), ast.Module):
            has_build = True
    if not has_build: add(0, 'no_build', 'the script must define a top-level build(K) function')
    return out


SAFE_BUILTINS = {k: __builtins__[k] if isinstance(__builtins__, dict) else getattr(__builtins__, k) for k in (
    'abs', 'all', 'any', 'bool', 'dict', 'divmod', 'enumerate', 'filter', 'float', 'int', 'isinstance', 'len', 'list', 'map',
    'max', 'min', 'pow', 'print', 'range', 'reversed', 'round', 'set', 'sorted', 'str', 'sum', 'tuple', 'zip', 'ValueError',
    'Exception', 'IndexError', 'KeyError', 'ZeroDivisionError', 'True', 'False', 'None')}


def _guarded_import(name, globals=None, locals=None, fromlist=(), level=0):
    if level or name.split('.')[0] not in ALLOWED_IMPORTS: raise ImportError(f'import {name} is not allowed')
    return __import__(name, globals, locals, fromlist, level)


def run(src, K):
    """Exec the (already checked) script with restricted builtins, then call build(K)."""
    b = dict(SAFE_BUILTINS); b['__import__'] = _guarded_import; b['__build_class__'] = __builtins__['__build_class__'] if isinstance(__builtins__, dict) else getattr(__builtins__, '__build_class__')
    ns = {'__builtins__': b, '__name__': 'scratch'}
    exec(compile(src, 'scratch.py', 'exec'), ns)
    return ns['build'](K)
// Cyrus meshgen RUNNER: "run sandboxed Blender" as an injected interface, plus the node-2 implementation.
// The worker never shells out itself: it hands a BlenderJob to a BlenderRunner and gets files back. The node-2 runner
// ships the fixed harness + modules + request (one tar over one ssh call, or a local bash on node-2 itself), runs
// ./blender/sbx-meshgen.sh there (build lock, systemd sandbox: no network, user nobody, read-only fs, /opt and /tank
// hidden, 4G / 400% / 256 tasks, tmpfs work dir) and reads back ONLY regular files from the work dir.
// SECURITY NOTE: a systemd unit is not a VM. Kernel escapes are untested. Production rung 3 needs an isolated worker.
// SERVER ONLY (node:child_process, node:fs).
import { spawn } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { NODE2, shq, sshRemote, tarball, type ExecResult, type Remote } from "../testflight/client";
import { pythonFilesFor } from "./templates";
import { cyrusConfig } from "../config";

export type BlenderJob = {
  /** Queue job id; becomes part of the node-2 job directory name. */
  jobId: string;
  /** The request.json the harness reads (built by the worker from a validated MeshgenRequest). */
  harnessRequest: Record<string, unknown>;
  /** Rung 3 only: the model-written script (already scanned). */
  scratchScript?: string;
  /** Whole budget for this run, lock wait included. */
  timeoutMs: number;
};

export type BlenderRunStatus = "ok" | "busy" | "timeout" | "crashed" | "transport";
export type BlenderRun = {
  status: BlenderRunStatus;
  exitCode: number | null;
  /** Parsed result.json (untrusted; the worker validates it). */
  result: unknown;
  /** work/ files by basename (glb, renders, sheet). */
  files: Map<string, Uint8Array>;
  logTail: string;
  wallMs: number;
  lockWaitMs: number;
  totalMs: number;
  /** sha256 over the shipped harness/module files: which code built this mesh. */
  filesSha256: string;
  runner: string;
  error?: string;
};

export interface BlenderRunner {
  readonly id: string;
  run(job: BlenderJob): Promise<BlenderRun>;
}

export const MESHGEN_ROOT = cyrusConfig().meshgenRoot;
/** The Blender 5.2.2 LTS portable build downloaded for the PoC (tarball sha256 checked then; see I-blender-poc.md). */
export const NODE2_BLENDER_DIR = cyrusConfig().blenderDir;
export const BLENDER_SOURCE_DIR = path.join(__dirname, "blender");
export const SANDBOX_SCRIPT = "sbx-meshgen.sh";

/** Run a command line on THIS host (for a worker that itself runs on node-2). */
export function localRemote(): Remote {
  return {
    exec: (command, opts = {}) => new Promise<ExecResult>((resolve) => {
      const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
      const out: Buffer[] = []; let stderr = "";
      child.stdout.on("data", (d: Buffer) => out.push(d));
      child.stderr.on("data", (d) => (stderr += d));
      const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
      child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout: Buffer.concat(out).toString("utf8"), stderr }); });
      child.stdin.on("error", () => {});
      child.stdin.end(opts.input ?? undefined);
    }),
  };
}

/** Minimal ustar reader: regular files only, names checked, caps on count and size. */
export function untar(buf: Uint8Array, caps = { maxEntries: 64, maxBytes: 80 * 1024 * 1024 }): Map<string, Uint8Array> {
  const out = new Map<string, Uint8Array>();
  let off = 0, total = 0;
  const str = (a: number, b: number) => Buffer.from(buf.subarray(a, b)).toString("utf8").replace(/\0.*$/s, "");
  while (off + 512 <= buf.length) {
    const h = buf.subarray(off, off + 512);
    if (h.every((x) => x === 0)) break;
    const name = (str(off + 345, off + 500) ? `${str(off + 345, off + 500)}/` : "") + str(off, off + 100);
    const size = parseInt(str(off + 124, off + 136).trim() || "0", 8);
    const type = String.fromCharCode(h[156] || 48);
    if (!Number.isFinite(size) || size < 0) throw new Error("corrupt tar header");
    const body = off + 512;
    if (body + size > buf.length) throw new Error("tar entry runs past the end");
    if (type === "0") {
      if (!name || name.startsWith("/") || name.split("/").includes("..")) throw new Error(`unsafe tar entry name ${name}`);
      if (out.size >= caps.maxEntries || (total += size) > caps.maxBytes) throw new Error("tar output exceeds the caps");
      out.set(name.replace(/^\.\//, ""), Uint8Array.from(buf.subarray(body, body + size)));
    }
    off = body + Math.ceil(size / 512) * 512;
  }
  return out;
}

const sha256 = (b: Uint8Array | string) => createHash("sha256").update(b).digest("hex");

export type Node2RunnerOptions = {
  remote?: Remote;
  /** "ssh" (default, from the primary) or "local" (the worker already runs on node-2). */
  transport?: "ssh" | "local";
  root?: string;
  blenderDir?: string;
  sourceDir?: string;
  readFile?: (p: string) => Uint8Array;
  /** Longest wait for node-2's build lock before the run counts as busy (default 600 s, never more than half the budget). */
  lockWaitSec?: number;
};

/** The code files shipped with every job and their combined hash. */
export function harnessFiles(sourceDir = BLENDER_SOURCE_DIR, read: (p: string) => Uint8Array = (p) => readFileSync(p)): { files: { name: string; data: Uint8Array }[]; sha256: string } {
  const names = [...pythonFilesFor(), SANDBOX_SCRIPT].sort();
  const files = names.map((n) => ({ name: n, data: read(path.join(sourceDir, n)) }));
  return { files, sha256: sha256(files.map((f) => `${f.name}\0${sha256(f.data)}\n`).join("")) };
}

export function createNode2BlenderRunner(opts: Node2RunnerOptions = {}): BlenderRunner {
  const transport = opts.transport ?? "ssh";
  const remote = opts.remote ?? (transport === "local" ? localRemote() : sshRemote(NODE2));
  const root = (opts.root ?? MESHGEN_ROOT).replace(/\/$/, "");
  const blender = opts.blenderDir ?? NODE2_BLENDER_DIR;
  const id = `node2-systemd-sandbox(${transport})`;
  return {
    id,
    async run(job) {
      const t0 = Date.now();
      const base: Omit<BlenderRun, "status"> = { exitCode: null, result: null, files: new Map(), logTail: "", wallMs: 0, lockWaitMs: 0, totalMs: 0, filesSha256: "", runner: id };
      const code = harnessFiles(opts.sourceDir, opts.readFile);
      base.filesSha256 = code.sha256;
      const slug = job.jobId.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40) || "job";
      const dir = `mg-${slug}-${randomBytes(4).toString("hex")}`;
      const J = `${root}/jobs/${dir}`;
      const totalSec = Math.max(60, Math.floor(job.timeoutMs / 1000));
      const lockWait = Math.max(5, Math.min(opts.lockWaitSec ?? 600, Math.floor(totalSec / 2)));
      const maxRun = Math.max(30, totalSec - lockWait - 20);
      const entries = [...code.files.map((f) => ({ name: `in/${f.name}`, data: Buffer.from(f.data) })),
        { name: "in/request.json", data: Buffer.from(JSON.stringify(job.harnessRequest)) },
        ...(job.scratchScript !== undefined ? [{ name: "in/scratch.py", data: Buffer.from(job.scratchScript, "utf8") }] : [])];
      const cmd = [
        `umask 022; J=${shq(J)}; mkdir -p "$J" && tar --no-same-owner -xf - -C "$J" || { echo "could not unpack the job" >&2; exit 90; }`,
        `bash "$J/in/${SANDBOX_SCRIPT}" "$J" ${shq(blender)} ${maxRun} ${lockWait} >/dev/null 2>"$J/sbx.err"; rc=$?`,
        `[ $rc -eq 0 ] || cat "$J/sbx.err" >&2`,
        `[ -s "$J/out.tar" ] && base64 -w0 "$J/out.tar"`,
        `case "$J" in ${shq(root + "/jobs/mg-")}*) rm -rf -- "$J" ;; esac`,
        `exit $rc`,
      ].join("\n");
      let r: ExecResult;
      try { r = await remote.exec(cmd, { input: tarball(entries), timeoutMs: job.timeoutMs }); }
      catch (e) { return { ...base, status: "transport", error: (e as Error).message.slice(0, 300), totalMs: Date.now() - t0 }; }
      base.totalMs = Date.now() - t0;
      const b64 = r.stdout.trim();
      if (r.code !== 0 || !b64) return { ...base, status: "transport", error: `build host returned ${r.code}: ${r.stderr.slice(0, 300) || "no output"}` };
      let files: Map<string, Uint8Array>;
      try { files = untar(Buffer.from(b64, "base64")); }
      catch (e) { return { ...base, status: "transport", error: `bad output archive: ${(e as Error).message}` }; }
      const text = (k: string) => { const f = files.get(k); return f ? Buffer.from(f).toString("utf8") : ""; };
      const num = (k: string) => { const n = parseInt(text(k).trim(), 10); return Number.isFinite(n) ? n : null; };
      if (!files.has("meta/exit")) return { ...base, status: "transport", error: "incomplete output archive (no exit status)" };
      base.exitCode = num("meta/exit"); base.wallMs = num("meta/wall_ms") ?? 0; base.lockWaitMs = num("meta/lock_wait_ms") ?? 0;
      base.logTail = text("meta/log.txt").slice(-4000);
      for (const [k, v] of files) if (k.startsWith("work/") && k !== "work/result.json") base.files.set(k.slice(5), v);
      if (base.exitCode === 75) return { ...base, status: "busy", error: "node-2's build lock was busy" };
      if (base.exitCode === 70) return { ...base, status: "transport", error: "could not mount the job's tmpfs on node-2" };
      if (base.exitCode === 124) return { ...base, status: "timeout", error: `Blender ran past ${maxRun} s and was killed` };
      const raw = files.get("work/result.json");
      if (!raw || raw.length > 4 * 1024 * 1024) return { ...base, status: "crashed", error: `no result.json (exit ${base.exitCode}); log: ${base.logTail.slice(-300)}` };
      try { base.result = JSON.parse(Buffer.from(raw).toString("utf8")); }
      catch { return { ...base, status: "crashed", error: "result.json does not parse" }; }
      return { ...base, status: "ok" };
    },
  };
}

