// Test Flight spec validation + resolution against the version registry. Pure (no I/O): fails closed on anything
// the registry cannot vouch for (unknown version, no pinned Paper server jar).
import { getVersion, type VersionRow } from "../versions/registry";
import type { CheckId, ResolvedSpec, TestFlightSpec, LogMatcher, ServerFile } from "./types";
import { CHECK_IDS } from "./types";
import { cyrusConfig } from "../config";
import { validatePlaytestPlan, playtestVersion } from "../playtest/plan";

export const TF_DEFAULT_ROOT = cyrusConfig().testFlightRoot;
export const DEFAULT_TIMEOUTS = { bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 } as const;
export const DEFAULT_MEMORY = { xmxMb: 1024, rssCapMb: 1800 } as const;
const RESERVED_COMMANDS = /^\/?(stop|restart|op|deop|reload)\b/i;
const SHA256 = /^[0-9a-f]{64}$/;
/** Same rule as lib.js SERVER_FILE_RE: relative, under plugins/, plain segments only. */
export const SERVER_FILE_RE = /^plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}){0,3}$/;
export const MAX_SERVER_FILES = 16;
export const MAX_SERVER_FILE_BYTES = 64 * 1024;
/** Same rules as lib.js (runner tf-lite-2). */
export const SEED_NAME_RE = /^[a-z0-9][a-z0-9._-]{0,63}$/;
export const SEED_TO_RE = /^(libraries|plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,4})$/;
export const COLLECT_RE = /^[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,7}\/?$/;
export const MAX_SEEDS = 8;
export const MAX_COLLECT = 12;

function checkFile(f: ServerFile | undefined, key: string, errs: string[]) {
  if (!f || typeof f.path !== "string" || !SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) errs.push(`${key}.path must be a relative path under plugins/ (plain segments)`);
  if (!f || typeof f.content !== "string" || Buffer.byteLength(f.content, "utf8") > MAX_SERVER_FILE_BYTES) errs.push(`${key}.content must be text of at most ${MAX_SERVER_FILE_BYTES} bytes`);
}

function checkMatchers(list: LogMatcher[] | undefined, key: string, errs: string[]) {
  for (const [i, m] of (list ?? []).entries()) {
    if (!m || typeof m.pattern !== "string" || !m.pattern) { errs.push(`${key}[${i}]: pattern is required`); continue; }
    if (m.pattern.length > 400) errs.push(`${key}[${i}]: pattern longer than 400 chars`);
    try { new RegExp(m.pattern, (m.flags ?? "").replace(/[^imsu]/g, "")); } catch (e) { errs.push(`${key}[${i}]: ${(e as Error).message}`); }
  }
}

export type PinnedRow = VersionRow & { paperBuild: number; paperServerSha256: string };
export type SpecCheck = { ok: true; row: PinnedRow } | { ok: false; errors: string[] };

/** Validate a caller spec. `lookup` is injectable for tests; defaults to the real registry. */
export function validateSpec(spec: TestFlightSpec, lookup: (id: string) => VersionRow | null = getVersion): SpecCheck {
  const errs: string[] = [];
  const row = lookup(String(spec?.version ?? ""));
  if (!row) errs.push(`Minecraft ${spec?.version} is not in the version registry`);
  else {
    if (!row.paperBuild || !Number.isInteger(row.paperBuild)) errs.push(`${row.id} has no pinned Paper server build, so it cannot be test-flown`);
    if (!SHA256.test(String(row.paperServerSha256 ?? ""))) errs.push(`${row.id} has no pinned Paper server sha256`);
  }
  const arts = [...(spec.plugins ?? []).map((a, i) => ["plugins", i, a] as const), ...(spec.datapacks ?? []).map((a, i) => ["datapacks", i, a] as const)];
  for (const [k, i, a] of arts) {
    const hasLocal = typeof a?.localPath === "string" && a.localPath.length > 0;
    const hasRemote = typeof a?.remotePath === "string" && a.remotePath.length > 0;
    if (hasLocal === hasRemote) errs.push(`${k}[${i}]: give exactly one of localPath or remotePath`);
    if (a?.sha256 != null && !SHA256.test(a.sha256)) errs.push(`${k}[${i}]: sha256 must be 64 lowercase hex chars`);
    if (k === "plugins" && !/\.jar$/.test(String(a?.localPath ?? a?.remotePath ?? ""))) errs.push(`plugins[${i}]: must be a .jar`);
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) if (!/^[a-z0-9_.-]{1,64}$/.test(String(d?.name ?? ""))) errs.push(`datapacks[${i}].name must be 1-64 chars of a-z 0-9 _ . -`);
  const pluginNames = new Set<string>();
  for (const p of spec.plugins ?? []) {
    const b = String(p.localPath ?? p.remotePath ?? "").split("/").pop()!;
    if (pluginNames.has(b)) errs.push(`two plugins share the file name ${b}`);
    pluginNames.add(b);
  }
  for (const [i, c] of (spec.rcon ?? []).entries()) {
    const cmd = String(c?.command ?? "");
    if (!cmd.trim() || cmd.length > 200 || /[\r\n]/.test(cmd)) errs.push(`rcon[${i}].command must be one line of 1-200 chars`);
    if (RESERVED_COMMANDS.test(cmd.trim())) errs.push(`rcon[${i}]: '${cmd}' is reserved for the runner`);
    if (c.expect != null && !Array.isArray(c.expect)) errs.push(`rcon[${i}].expect must be an array of strings`);
    if (c.writeFile != null) checkFile(c.writeFile, `rcon[${i}].writeFile`, errs);
    if (c.waitMs != null && !(Number.isInteger(c.waitMs) && c.waitMs >= 0 && c.waitMs <= 30000)) errs.push(`rcon[${i}].waitMs must be 0-30000`);
  }
  if ((spec.files ?? []).length > MAX_SERVER_FILES) errs.push(`files: at most ${MAX_SERVER_FILES}`);
  for (const [i, f] of (spec.files ?? []).entries()) checkFile(f, `files[${i}]`, errs);
  if ((spec.seeds ?? []).length > MAX_SEEDS) errs.push(`seeds: at most ${MAX_SEEDS}`);
  for (const [i, sd] of (spec.seeds ?? []).entries()) {
    if (!SEED_NAME_RE.test(String(sd?.from ?? ""))) errs.push(`seeds[${i}].from must be a seed name under <root>/seeds`);
    if (!SEED_TO_RE.test(String(sd?.to ?? "")) || String(sd?.to).split("/").includes("..")) errs.push(`seeds[${i}].to must be libraries or a path under plugins/`);
  }
  if ((spec.collect ?? []).length > MAX_COLLECT) errs.push(`collect: at most ${MAX_COLLECT}`);
  for (const [i, c] of (spec.collect ?? []).entries()) {
    if (typeof c !== "string" || !COLLECT_RE.test(c) || c.split("/").includes("..")) errs.push(`collect[${i}] must be a relative path of plain segments`);
  }
  checkMatchers(spec.logMatchers, "logMatchers", errs);
  checkMatchers(spec.logIgnore, "logIgnore", errs);
  if (spec.logMatchers && spec.logMatchers.length === 0) errs.push("logMatchers: an empty list would make the log check vacuous; omit it to use the defaults");
  const t = spec.timeouts ?? {};
  for (const [k, max] of [["bootSec", 600], ["rconSec", 60], ["stopSec", 120], ["totalSec", 900]] as const) {
    const v = t[k];
    if (v != null && !(Number.isFinite(v) && v > 0 && v <= max)) errs.push(`timeouts.${k} must be 1-${max}`);
  }
  const m = spec.memory ?? {};
  if (m.xmxMb != null && !(Number.isInteger(m.xmxMb) && m.xmxMb >= 256 && m.xmxMb <= 1024)) errs.push("memory.xmxMb must be 256-1024 (node-2 allows at most -Xmx1g)");
  if (m.rssCapMb != null && !(Number.isInteger(m.rssCapMb) && m.rssCapMb >= 512 && m.rssCapMb <= 2048)) errs.push("memory.rssCapMb must be 512-2048");
  for (const s of spec.requireStages ?? []) if (!(CHECK_IDS as readonly string[]).includes(s)) errs.push(`requireStages: unknown stage ${s}`);
  if (spec.world != null && (Object.keys(spec.world).some((k) => k !== "generateStructures") || (spec.world.generateStructures != null && typeof spec.world.generateStructures !== "boolean"))) errs.push("world may only hold generateStructures (boolean)");
  if (spec.playtest != null) {
    errs.push(...validatePlaytestPlan(spec.playtest));
    const pv = playtestVersion(String(spec.version));
    if (!pv.ok) errs.push(pv.reason);
  }
  if (errs.length || !row) return { ok: false, errors: errs };
  return { ok: true, row: row as PinnedRow };
