// Cyrus Server Doctor (wiring phase 2): the ADMIN-ONLY, READ-ONLY invocation path behind
// app/api/admin/cyrus/doctor (framework-free, deps injected). POST { userId, serverId }:
//   CYRUS_SERVER_DOCTOR=1 (else 404) -> a Cyrus admin (the /admin/cyrus gate: role area + private preview list; else
//   404) -> rate limit -> the server must belong to `userId` (the host's file access refuses anyone else's server,
//   a deleting server, or a non-owner: 404) -> runDoctor over that read-only view (no console: the Doctor sends no
//   command from this path) -> audit row -> the report + its plain-text rendering.
// Nothing on the server is written, restarted or run.
import { DOCTOR_FLAG, doctorEnabled, renderDoctorText, runDoctor, type DoctorReport } from "./doctor";
import type { ReadOnlyServerFs } from "../inventory/types";

type Env = Record<string, string | undefined>;
export type DoctorApiDeps = {
  env: Env;
  /** The acting Cyrus admin, or null (never throws for "not allowed"). */
  admin(): Promise<{ id: string } | null>;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec: number };
  /** READ-ONLY file view of `serverId` when it belongs to `userId` (null otherwise). */
  openReadOnly(userId: string, serverId: string): Promise<{ fs: ReadOnlyServerFs; base: string; close?: () => void } | null>;
  audit(adminId: string, detail: string): Promise<void>;
  now?: () => Date;
};

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const ID = /^[A-Za-z0-9_-]{1,64}$/;

/** Only the read methods reach the Doctor, whatever the host object also has. */
export const readOnlyView = (fs: ReadOnlyServerFs): ReadOnlyServerFs => ({ stat: (p) => fs.stat(p), readFile: (p, m) => fs.readFile(p, m), list: (d) => fs.list(d) });

export async function handleAdminDoctor(req: Request, d: DoctorApiDeps): Promise<Response> {
  if (!doctorEnabled(d.env)) return json(404, { error: "Not found" });
  const admin = await d.admin().catch(() => null);
  if (!admin) return json(404, { error: "Not found" });
  const rl = d.rateLimit(`cyrus:doctor:${admin.id}`, 20, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Retry in ${rl.retryAfterSec}s.`, code: "rate_limited" });
  const b = (await req.json().catch(() => null)) as Record<string, unknown> | null;
  const userId = typeof b?.userId === "string" && ID.test(b.userId) ? b.userId : null;
  const serverId = typeof b?.serverId === "string" && ID.test(b.serverId) ? b.serverId : null;
  if (!userId || !serverId) return json(400, { error: "Send userId and serverId.", code: "bad_body" });
  const view = await d.openReadOnly(userId, serverId).catch(() => null);
  if (!view) return json(404, { error: "That server does not belong to that account (or is gone).", code: "not_found" });
  let report: DoctorReport;
  try { report = await runDoctor(readOnlyView(view.fs), { base: view.base, console: null, now: d.now }); }
  catch (e) { return json(502, { error: `The Doctor could not read the server: ${(e as Error).message.slice(0, 200)}`, code: "unreachable" }); }
  finally { view.close?.(); }
  await d.audit(admin.id, `${serverId} owner=${userId} ${report.overall} problems=${report.counts.problems} warnings=${report.counts.warnings}`).catch(() => {});
  return json(200, { flag: DOCTOR_FLAG, report, text: renderDoctorText(report) });
}

/** Today's host wiring (Cyrus host seam only). */
export async function hostDoctorDeps(): Promise<DoctorApiDeps> {
  const { getHost } = await import("../host");
  const { requireCyrusAdmin } = await import("../admin/gate");
  const host = getHost();
  return {
    env: process.env,
    admin: async () => { try { return await requireCyrusAdmin("builds"); } catch (e) { if ((e as { digest?: string }).digest?.startsWith("NEXT_")) throw e; return null; } },
    rateLimit: (key, max, windowMs) => host.rateLimit.check(key, { max, windowMs }),
    openReadOnly: async (userId, serverId) => host.servers.openFiles(userId, serverId),
    audit: (adminId, detail) => host.audit.record(adminId, "cyrus.doctor.run", detail),
  };
}
