/** Web side: a RenderHost that forwards to the worker's relay (loopback only). */
export function relayRenderHost(url: string, token: string, fetchImpl: typeof fetch = fetch): RenderHost {
  const u = new URL(url);
  if (u.protocol !== "http:" || !["127.0.0.1", "localhost", "[::1]"].includes(u.hostname)) throw new Error("the sound relay must be a loopback http URL (it runs in the worker on the same host)");
  if (token.length < RELAY_TOKEN_MIN) throw new Error(`CYRUS_SOUND_RELAY_TOKEN must be at least ${RELAY_TOKEN_MIN} characters`);
  const base = u.origin;
  const post = async <T>(path: string, job: unknown, timeoutMs: number): Promise<T> => {
    const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), timeoutMs);
    try {
      const r = await fetchImpl(`${base}${path}`, { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify(job), signal: ctl.signal });
      const text = await r.text();
      if (text.length > MAX_JOB_OUTPUT_BYTES * 1.4) return { ok: false, code: "transport", error: "render output too large" } as T;
      return JSON.parse(text) as T;
    } catch (e) { return { ok: false, code: "transport", error: `the sound relay is not reachable: ${(e as Error).message}` } as T; }
    finally { clearTimeout(t); }
  };
  return {
    id: `relay:${base}`,
    render: (job) => post<RenderResult>("/render", job, 420_000),
    preview: (job) => post<PreviewResult>("/preview", job, 140_000),
  };
}

/** Web side health probe of the relay (+ the render host behind it). */
export async function relayHealth(url: string, token: string, fetchImpl: typeof fetch = fetch): Promise<RenderHealth> {
  const t0 = Date.now();
  try {
    const r = await fetchImpl(`${new URL(url).origin}/health`, { headers: { Authorization: `Bearer ${token}` }, signal: AbortSignal.timeout(40_000) });
    return (await r.json()) as RenderHealth;
  } catch (e) { return { ok: false, host: `relay:${url}`, checks: [{ id: "reachable", ok: false, detail: (e as Error).message }], ms: Date.now() - t0 }; }
}
